class FileDataPduTest : public ::testing::Test {};

TEST_F(FileDataPduTest, SerializeDeserializeRoundTrip) {
    U8 data[] = {0x01, 0x02, 0x03, 0x04, 0x05};
    FileDataPdu original;
    original.offset = 0;
    original.data = data;
    original.dataSize = sizeof(data);

    U8 buf[64];
    U32 serializedSize = original.serialize(buf, sizeof(buf));
    EXPECT_EQ(static_cast<U32>(4 + sizeof(data)), serializedSize);

    FileDataPdu parsed;
    U32 parsedSize = parsed.deserialize(buf, serializedSize, false);
    EXPECT_EQ(serializedSize, parsedSize);

    EXPECT_EQ(original.offset, parsed.offset);
    EXPECT_EQ(original.dataSize, parsed.dataSize);
    EXPECT_EQ(0, std::memcmp(data, parsed.data, parsed.dataSize));
}

TEST_F(FileDataPduTest, DeserializeFromSpacepackets) {
    const U8* dataField = REF_FILE_DATA_PDU + HEADER_SIZE;
    const U32 dataFieldLen = sizeof(REF_FILE_DATA_PDU) - HEADER_SIZE;

    FileDataPdu parsed;
    U32 parsedSize = parsed.deserialize(dataField, dataFieldLen, false);
    EXPECT_GT(parsedSize, static_cast<U32>(0));

    EXPECT_EQ(static_cast<U32>(0), parsed.offset);
    EXPECT_EQ(static_cast<U32>(5), parsed.dataSize);
    EXPECT_EQ(0x01, parsed.data[0]);
    EXPECT_EQ(0x05, parsed.data[4]);
}

TEST_F(FileDataPduTest, DeserializeFromSpacepacketsWithOffset) {
    const U8* dataField = REF_FILE_DATA_PDU_OFFSET10 + HEADER_SIZE;
    const U32 dataFieldLen = sizeof(REF_FILE_DATA_PDU_OFFSET10) - HEADER_SIZE;

    FileDataPdu parsed;
    U32 parsedSize = parsed.deserialize(dataField, dataFieldLen, false);
    EXPECT_GT(parsedSize, static_cast<U32>(0));

    EXPECT_EQ(static_cast<U32>(10), parsed.offset);
    EXPECT_EQ(static_cast<U32>(3), parsed.dataSize);
    EXPECT_EQ(0xAA, parsed.data[0]);
    EXPECT_EQ(0xBB, parsed.data[1]);
    EXPECT_EQ(0xCC, parsed.data[2]);
}

TEST_F(FileDataPduTest, SerializeMatchesSpacepackets) {
    U8 data[] = {0x01, 0x02, 0x03, 0x04, 0x05};
    FileDataPdu fileData;
    fileData.offset = 0;
    fileData.data = data;
    fileData.dataSize = sizeof(data);

    PduHeader header;
    header.version = CFDP_VERSION;
    header.pduType = PduType::FILE_DATA;
    header.direction = Direction::TOWARD_RECEIVER;
    header.mode = TransmissionMode::UNACKNOWLEDGED;
    header.crcFlag = false;
    header.largeFileFlag = false;
    header.dataFieldLength = static_cast<U16>(4 + sizeof(data));
    header.segmentationControl = false;
    header.entityIdLength = 1;
    header.segmentMetadataFlag = false;
    header.seqNumLength = 1;
    header.sourceEntityId = 1;
    header.transactionSeqNum = 1;
    header.destinationEntityId = 2;

    U8 fullPdu[64];
    U32 totalLen = serializeFileDataPdu(header, fileData, fullPdu, sizeof(fullPdu));
    ASSERT_GT(totalLen, static_cast<U32>(0));

    EXPECT_EQ(sizeof(REF_FILE_DATA_PDU), totalLen);
    for (U32 i = 0; i < totalLen; i++) {
        EXPECT_EQ(REF_FILE_DATA_PDU[i], fullPdu[i])
            << "Mismatch at byte " << i;
    }
}

TEST_F(FileDataPduTest, DeserializeTooSmallBuffer) {
    FileDataPdu parsed;
    U8 buf[] = {0x00, 0x00};
    U32 parsedSize = parsed.deserialize(buf, sizeof(buf), false);
    EXPECT_EQ(static_cast<U32>(0), parsedSize);
}

