    const U8* eofParams = REF_EOF_PDU + HEADER_SIZE + 1;
    const U32 eofParamsLen = sizeof(REF_EOF_PDU) - HEADER_SIZE - 1;

    EofPdu parsed;
    U32 parsedSize = parsed.deserialize(eofParams, eofParamsLen, false);
    EXPECT_GT(parsedSize, static_cast<U32>(0));

    EXPECT_EQ(ConditionCode::NO_ERROR, parsed.conditionCode);
    EXPECT_EQ(static_cast<U32>(0x12345678), parsed.fileChecksum);
