// -----------------------------------------------------------------------
// FinishedPdu Tests
// -----------------------------------------------------------------------

class FinishedPduTest : public ::testing::Test {};

TEST_F(FinishedPduTest, SerializeDeserializeRoundTrip) {
    FinishedPdu original;
    original.conditionCode = ConditionCode::NO_ERROR;
    original.deliveryCode = DeliveryCode::DATA_COMPLETE;
    original.fileStatus = FileStatus::DISCARDED_DELIBERATELY;

    U8 buf[4];
    U32 serializedSize = original.serialize(buf, sizeof(buf));
    EXPECT_EQ(static_cast<U32>(1), serializedSize);

    FinishedPdu parsed;
    U32 parsedSize = parsed.deserialize(buf, serializedSize);
    EXPECT_EQ(static_cast<U32>(1), parsedSize);

    EXPECT_EQ(original.conditionCode, parsed.conditionCode);
    EXPECT_EQ(original.deliveryCode, parsed.deliveryCode);
    EXPECT_EQ(original.fileStatus, parsed.fileStatus);
}

TEST_F(FinishedPduTest, DeserializeFromSpacepackets) {
    // Finished data field: after header + directive code
    const U8* finishedParams = REF_FINISHED_PDU + HEADER_SIZE + 1;
    const U32 finishedParamsLen = sizeof(REF_FINISHED_PDU) - HEADER_SIZE - 1;

    FinishedPdu parsed;
    U32 parsedSize = parsed.deserialize(finishedParams, finishedParamsLen);
    EXPECT_EQ(static_cast<U32>(1), parsedSize);

    EXPECT_EQ(ConditionCode::NO_ERROR, parsed.conditionCode);
    EXPECT_EQ(DeliveryCode::DATA_COMPLETE, parsed.deliveryCode);
    EXPECT_EQ(FileStatus::DISCARDED_DELIBERATELY, parsed.fileStatus);
}

TEST_F(FinishedPduTest, BitFieldLayout) {
    // Per CCSDS 727.0-B-5 Table 5-7:
    // conditionCode(4) | spare(1) | deliveryCode(1) | fileStatus(2)
    //
    // Test with non-zero values to verify bit positions
    FinishedPdu original;
    original.conditionCode = ConditionCode::CANCEL_REQUEST_RECEIVED;  // 0x0F
    original.deliveryCode = DeliveryCode::DATA_INCOMPLETE;  // 1
    original.fileStatus = FileStatus::DISCARDED_FILESTORE_REJECTION;  // 2

    U8 buf[4];
    U32 serializedSize = original.serialize(buf, sizeof(buf));
    EXPECT_EQ(static_cast<U32>(1), serializedSize);

    // Expected byte: 0xF0 | 0x04 | 0x01 = 0xF5
    // conditionCode(0x0F) << 4 = 0xF0
    // deliveryCode(1) << 2 = 0x04
    // fileStatus(1) = 0x01
    EXPECT_EQ(0xF5, buf[0]);

    FinishedPdu parsed;
    parsed.deserialize(buf, 1);
    EXPECT_EQ(ConditionCode::CANCEL_REQUEST_RECEIVED, parsed.conditionCode);
    EXPECT_EQ(DeliveryCode::DATA_INCOMPLETE, parsed.deliveryCode);
    EXPECT_EQ(FileStatus::DISCARDED_FILESTORE_REJECTION, parsed.fileStatus);
}

TEST_F(FinishedPduTest, DeserializeTooSmallBuffer) {
    FinishedPdu parsed;
    U32 parsedSize = parsed.deserialize(nullptr, 0);
    EXPECT_EQ(static_cast<U32>(0), parsedSize);
}

// -----------------------------------------------------------------------
// Utility function tests
// -----------------------------------------------------------------------

TEST(SerializeDirectivePdu, BasicSerialization) {
    PduHeader header;
    header.version = CFDP_VERSION;
    header.pduType = PduType::FILE_DIRECTIVE;
    header.direction = Direction::TOWARD_RECEIVER;
    header.mode = TransmissionMode::UNACKNOWLEDGED;
    header.crcFlag = false;
    header.largeFileFlag = false;
    header.dataFieldLength = 2;  // 1 byte directive + 1 byte params
    header.segmentationControl = false;
    header.entityIdLength = 1;
    header.segmentMetadataFlag = false;
    header.seqNumLength = 1;
    header.sourceEntityId = 1;
    header.transactionSeqNum = 1;
    header.destinationEntityId = 2;

    U8 params[] = {0x42};
    U8 buf[64];
    U32 totalLen = serializeDirectivePdu(
        header, DirectiveCode::METADATA_PDU,
        params, 1, buf, sizeof(buf)
    );

    EXPECT_EQ(HEADER_SIZE + 2, totalLen);  // header + directive code + 1 byte params
    // Directive code should be at offset HEADER_SIZE
    EXPECT_EQ(static_cast<U8>(DirectiveCode::METADATA_PDU), buf[HEADER_SIZE]);
    EXPECT_EQ(0x42, buf[HEADER_SIZE + 1]);
}

TEST(SerializeDirectivePdu, BufferTooSmall) {
    PduHeader header;
    header.version = CFDP_VERSION;
    header.pduType = PduType::FILE_DIRECTIVE;
    header.direction = Direction::TOWARD_RECEIVER;
    header.mode = TransmissionMode::UNACKNOWLEDGED;
    header.crcFlag = false;
    header.largeFileFlag = false;
    header.dataFieldLength = 2;
    header.segmentationControl = false;
    header.entityIdLength = 1;
    header.segmentMetadataFlag = false;
    header.seqNumLength = 1;
    header.sourceEntityId = 1;
    header.transactionSeqNum = 1;
    header.destinationEntityId = 2;

    U8 params[] = {0x42};
    U8 buf[4];  // Too small
    U32 totalLen = serializeDirectivePdu(
        header, DirectiveCode::METADATA_PDU,
        params, 1, buf, sizeof(buf)
    );
    EXPECT_EQ(static_cast<U32>(0), totalLen);
}

